new file mode 100644
index 0000000..4d77c2c
--- /dev/null
+++ b/tests/access.test.js
@@ -0,0 +1,56 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, bearer, KEYS } from "./helpers.js";
+
+test("no key or an unknown key is 401", async () => {
+  const { raw } = app();
+  const none = await raw({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const wrong = await raw({ path: "/items", headers: bearer("nope") });
+  assert.equal(wrong.status, 401);
+  const basic = await raw({ path: "/items", headers: { Authorization: `Basic ${KEYS.manager}` } });
+  assert.equal(basic.status, 401);
+  const cased = await raw({ path: "/items", headers: { Authorization: `bearer ${KEYS.viewer}` } });
+  assert.equal(cased.status, 200);
+});
+
+test("viewers may only read", async () => {
+  const { handle, store } = app();
+  const h = bearer(KEYS.viewer);
+  assert.equal((await handle({ path: "/items", headers: h })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const cook = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: h });
+  assert.equal(cook.status, 403);
+  assert.equal(cook.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal((await handle({ path: "/audit", headers: h })).status, 403);
+});
+
+test("cooks cook, waste, log temperatures and count, but nothing else", async () => {
+  const { handle } = app();
+  const h = bearer(KEYS.cook);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: h })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/6/waste", body: { qty: 0.5 }, headers: h })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 }, headers: h })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" }, headers: h })).status, 403);
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 12 }, headers: h })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: h })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 4, qty: 1 }] }, headers: h })).status, 403);
+  assert.equal((await handle({ path: "/audit", headers: h })).status, 403);
+});
+
+test("changes are audited, newest first, for managers", async () => {
+  const { handle, raw } = app();
+  await handle({ path: "/items" });
+  await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: bearer(KEYS.cook) });
+  await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" }, headers: bearer(KEYS.cook) });
+  await raw({ method: "POST", path: "/jobs/nightly" });
+  const audit = (await handle({ path: "/audit" })).body;
+  assert.deepEqual(audit.map(({ keyName, method, path, status }) => ({ keyName, method, path, status })), [
+    { keyName: "line cook", method: "POST", path: "/stocktakes", status: 403 },
+    { keyName: "line cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+  ]);
+  assert.equal(audit[0].at, "2026-10-28T10:00:00.000Z");
+});
